 void Update(){GuideTick(FilmClock.Delta);if(music){music.Volume=save.musicVolume;music.Duck=playing||guidePractice;}if(portrait&&Input.GetKeyDown(KeyCode.Return))NextStory();if(Input.GetKeyDown(KeyCode.F12))Capture(Path.Combine(Application.persistentDataPath,"screenshot.png"));if(Input.GetKeyDown(KeyCode.Space))GameKey(KeyCode.Space);if(Input.GetKeyDown(KeyCode.Escape)){if(modal)CloseModal();else if(inGame)ShowMenu();}if(Input.GetKeyDown(KeyCode.Z))GameKey(KeyCode.Z);if(Input.GetKeyDown(KeyCode.X))GameKey(KeyCode.X);if(Input.GetKeyDown(KeyCode.E))GameKey(KeyCode.E);if(boat){float bob=Mathf.Sin(Time.unscaledTime*1.2f)*3;boat.anchoredPosition=new Vector2(boatX,-350+bob);}if(!playing)return;elapsed+=FilmClock.Delta;if(elapsed<.7f)return;elapsed-=.7f;beat++;if(beat>=8){playing=false;beat=-1;playLabel.text="听 曲";UpdateSlots();if(partialAudition){SetFeedback("此处余音已尽。完整听曲后，方可收入新景。");return;}RecordSceneOutcome();if(!freeMode&&board.Matches(Content.Levels[level])&&ExplorationReady())Complete();else if(!freeMode){SetFeedback(PuzzleFeedback());GuideFailure();}else FinishSecretSong();return;}ScoreBeat(beat);Sound(board.cells[beat]);for(int i=0;i<8;i++)markers[i].color=i==beat?new Color(.65f,.28f,.21f,.22f):new Color(.3f,.35f,.3f,.04f);if(!board.cells[beat].Empty){StartCoroutine(Ripple(115+beat*119,460,tones[board.cells[beat].tone]));if(Content.Levels[level].chapter==0&&board.cells[beat].tone==Content.Levels[level].target[beat].tone&&board.cells[beat].rank==Content.Levels[level].target[beat].rank)boatX=Mathf.Min(930,boatX+(board.cells[beat].rank==2?55:25));}UpdateSlots();}
